with base as (select *, stock_qty - price as stock_qty_minus_price from products where supplier_id is not null) select *, dense_rank() over (partition by category order by price nulls first) as price_dense_rank, first_value(cost, true) over (partition by brand, category order by stock_qty, id rows between unbounded preceding and current row) as first_known_cost, percent_rank() over (partition by supplier_id, category order by price desc nulls first) as price_percent_rank, min(price) over (partition by category, brand) as category_min_price from base;
